r('<th scope="col">Score</th>','<th scope="col">Score</th><th scope="col">Band</th>')
r('''                <td data-testid="person-score">{{ scoreOf(p.id) }}</td>''','''                <td data-testid="person-score">{{ scoreOf(p.id) }}</td>
                <td data-testid="person-band">{{ bandOf(p.id) }}</td>''')
r("import { SheetReviewSla } from '../settings/sheet-review-sla';","import { SheetReviewSla } from '../settings/sheet-review-sla';\nimport { SheetScoreBands } from '../settings/sheet-score-bands';")
r("  private readonly reviewSla = inject(SheetReviewSla);","  private readonly reviewSla = inject(SheetReviewSla);\n  private readonly scoreBands = inject(SheetScoreBands);")
r('''  /** The due of the person's settled and of their open claims that count, in cents. */''','''  /** The person's band while both score thresholds are set: HIGH at or above the high one, MID at or
   *  above the mid one, else LOW; blank while either threshold is blank. */
  protected bandOf(personId: number): string {
    const mid = this.scoreBands.mid();
    const high = this.scoreBands.high();
    if (mid === null || high === null) return '';
    const score = Number(this.scoreOf(personId));
    return score >= high ? 'HIGH' : score >= mid ? 'MID' : 'LOW';
  }

  /** The due of the person's settled and of their open claims that count, in cents. */''')
open(p,'w').write(s)
