test("score bands scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "perm-void", "steward");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "99.95", "note": ""})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "contact": "ADA@X"}));
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "contact": " Ada@x ", "tags": "a"})).toBeNull();
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "70.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "20.00"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Ben", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "25.00", "start": "2026-03-09", "end": "2026-04-30", "day": "1"}));
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25", "tags": "b,a,a"}));
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "C", "gradeFrom": "2026-03-05"})).toBe(true);
  expect(await ui.movePerson(pg_uma, p_ben, "up")).toBe(false);
  expect(await ui.search(pg_uma, "zz")).toEqual([]);
  expect(await ui.claimAction(pg_uma, c_ben_0, "void", "late")).toBe(false);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  expect(await ui.watch(pg_uma, p_ben, true)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.importOpenings(pg_uma, "Ada,2026-02,5.50")).toBe(1);
  expect(await ui.editInline(pg_uma, c_ben_0, "10.25")).toBe(true);
  expect(await ui.snapshotCompare(pg_uma, "2026-04-05", "2026-04-05")).toEqual(["Ben", "Ada"]);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.importRates(pg_uma, "C,10.00\nC,33.33,2026-03-05")).toBe(2);
  expect(await ui.editClaim(pg_uma, c_ben_0, {"date": "2026-03-28"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ben_0, "void", "late")).toBe(false);
  await ui.refresh(pg_uma);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.unstate(pg_wes, p_ada)).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.reassign(pg_wes, c_ben_0, "Ada")).toBe(true);
  expect(await ui.retire(pg_wes, p_ben, "2026-02-10")).toBe(true);
  expect(await ui.editClaim(pg_wes, c_ben_0, {"amount": "7.77"})).toBe(true);
  expect(await ui.importRates(pg_wes, "A,33.33\nB,20.00,2026-03-05")).toBe(2);
  expect(await ui.claimAction(pg_wes, c_ben_0, "void", "late")).toBe(true);
  expect(await ui.hold(pg_wes, p_ada, {"from": "2026-03-15", "to": "2026-03-20"})).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_ben)).toHaveCount(0);
  expect(await ui.statement(pg_wes, p_ada)).toBe(true);
  await ui.setAsOf(pg_wes, "2026-02-25");
  await ui.refresh(pg_wes);
  await ui.expectAudit(sheet, [
  ]);
  await ui.clearAsOf(pg_wes);
  await ui.refresh(pg_wes);

